{"path":"packages/appboundry-host/test/outbox-outcome.test.ts","content":"/**
 * performOutbox (transactions.ts) when the outcome write cannot be recorded: the result it reports
 * must match the durable record, never a done or failed that was not written (issue #99).
 */
import { describe, expect, it } from "vitest";
import { performOutbox, type OutboxRecord } from "../src/transactions.js";

type Stored = OutboxRecord & { __version: number };

/** A one-record store; outcome writes (every write after the claim) fail `failures` times. */
function store(failures: number) {
  let record: Stored = {
    id: "outbox_x_1", requestId: "r1", function: "log:pay", principalId: "dev",
    effect: { service: "jobs", method: "enqueue", type: "t", payload: {} },
    state: "pending", createdAt: 1, updatedAt: 1, attempts: 0, __version: 1
  };
  let writes = 0;
  const db = {
    collection: () => ({ get: async () => ({ ...record }), find: async () => [{ ...record }] }),
    transaction: async (request: { operations: Array<{ ifVersion: number; value: OutboxRecord }> }) => {
      const op = request.operations[0]!;
      writes += 1;
      if (writes > 1 && failures > 0) {
        failures -= 1;
        throw new Error("store unavailable");
      }
      if (op.ifVersion !== record.__version) throw new Error("CONFLICT");
      record = { ...op.value, __version: record.__version + 1 } as Stored;
    }
  };
  return { db, current: () => record };
}

describe("performOutbox outcome write", () => {
  it("does not report done when done could not be recorded", async () => {
    const s = store(Infinity);
    const warnings: string[] = [];
    const outcome = await performOutbox(s.db as never, "outbox_x_1", async () => ({ jobId: "j1" }), m => warnings.push(m));
    expect(s.current().state).toBe("performing");
    expect(outcome).toBe("skipped");
    expect(warnings.join("\n")).toMatch(/could not record done/);
  });

  it("does not report failed when failed could not be recorded", async () => {
    const s = store(Infinity);
    const outcome = await performOutbox(s.db as never, "outbox_x_1", async () => { throw new Error("boom"); });
    expect(s.current().state).toBe("performing");
    expect(outcome).toBe("skipped");
  });

  it("retries a transiently failing outcome write and records it", async () => {
    const s = store(1);
    const outcome = await performOutbox(s.db as never, "outbox_x_1", async () => ({ jobId: "j1" }));
    expect(outcome).toBe("done");
    expect(s.current()).toMatchObject({ state: "done", attempts: 1, result: { jobId: "j1" } });
  });
});
"}

